def refs():
    return [{**s, "subject": "math", "locator": "鄰補角、對頂角、三角形外角、四邊形內角和、正多邊形內外角與平行線截線角", "observedPattern": "公開數學評量常把角的互補與對頂關係、三角形外角定理、多邊形內角和及正多邊形外角總和結合，要求先辨識幾何關係再計算；本題只取能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-math-performance-s-iv-2-{n}", "subject": "math", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三份公立學校／公開會考數學試題僅供角關係、多邊形與平行線截線角能力方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開數學試題的角與多邊形方向獨立改寫；題幹、數值、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "兩個互為鄰補角的角，其中一角為 74°，另一角是多少？", {"A": "74°", "B": "96°", "C": "106°", "D": "180°"}, "C", "鄰補角的和為 180°，所以另一角=180°-74°=106°，選 C。", "看到鄰補角先寫總和 180°，再用減法求未知角。", ["確認兩角是鄰補角。", "寫出兩角和為 180°。", "令未知角為 180°-74°。", "計算得到 106°。", "所以選 C。"], "easy"),
    make(2, "兩條直線相交形成對頂角，其中一角為 58°，它的對頂角是多少？", {"A": "58°", "B": "122°", "C": "180°", "D": "29°"}, "A", "對頂角相等，因此與 58° 對頂的角也是 58°，選 A。", "先判斷是對頂角，不要把相鄰的鄰補角拿來計算。", ["確認兩角由兩條相交直線形成。", "題目指定的是對頂位置。", "使用對頂角相等。", "直接得到未知角為 58°。", "所以選 A。"], "easy"),
    make(3, "三角形的一個外角為 128°，其中一個不相鄰的內角為 53°，另一個不相鄰內角是多少？", {"A": "53°", "B": "65°", "C": "75°", "D": "128°"}, "C", "三角形外角等於兩個不相鄰內角和，因此另一角=128°-53°=75°，選 C。", "辨認外角定理的兩個遠端內角，再用總和減已知角。", ["確認 128° 是三角形外角。", "外角等於兩個不相鄰內角的和。", "列式 53°+x=128°。", "解得 x=75°。", "所以選 C。"], "medium"),
    make(4, "四邊形的三個內角為 72°、98°、121°，第四個內角是多少？", {"A": "59°", "B": "69°", "C": "79°", "D": "89°"}, "B", "四邊形內角和為 360°；已知角和為 291°，第四角=360°-291°=69°，選 B。", "先求多邊形總內角和，再扣除所有已知角。", ["四邊形內角和為 (4-2)×180°=360°。", "計算已知角和 72+98+121=291°。", "用 360°-291°。", "得到第四角 69°。", "所以選 B。"], "easy"),
    make(5, "正六邊形的每一個外角是多少？", {"A": "45°", "B": "60°", "C": "72°", "D": "90°"}, "B", "任一凸多邊形外角和為 360°；正六邊形各外角相等，所以每角=360°÷6=60°，選 B。", "正多邊形外角直接用 360° 除以邊數。", ["確認正六邊形有 6 個相等外角。", "所有外角總和為 360°。", "計算 360°÷6。", "得到每個外角 60°。", "所以選 B。"], "easy"),
    make(6, "正十邊形的一個外角是多少？", {"A": "18°", "B": "30°", "C": "36°", "D": "45°"}, "C", "正十邊形的十個外角相等，總和 360°，每個為 360°÷10=36°，選 C。", "先利用外角總和固定為 360°，再除以邊數。", ["辨認邊數 n=10。", "外角總和為 360°。", "正十邊形各外角相等。", "計算 360°÷10=36°。", "所以選 C。"], "easy"),
    make(7, "六邊形的五個外角依序為 55°、65°、70°、80°、45°，第六個外角是多少？", {"A": "35°", "B": "45°", "C": "55°", "D": "65°"}, "B", "六邊形外角和為 360°；前五角和 315°，第六角=360°-315°=45°，選 B。", "不必知道圖形形狀，只要使用所有外角總和 360°。", ["寫出六邊形外角總和 360°。", "計算前五角和 55+65+70+80+45=315°。", "用總和減已知和。", "得到第六角 45°。", "所以選 B。"], "medium"),
    make(8, "兩條平行線被一條截線所截，某一個銳角為 63°，與它相等的對應角是多少？", {"A": "63°", "B": "117°", "C": "90°", "D": "126°"}, "A", "平行線被截線截出時，對應角相等；因此對應角也是 63°，選 A。", "先辨認『對應角』這個位置關係，再使用平行線角性質。", ["確認兩條直線平行。", "題目指定兩角為對應角。", "平行線的對應角相等。", "將已知 63° 保持不變。", "所以選 A。"], "easy"),
    make(9, "正多邊形的每一個內角為 144°，這個正多邊形有幾邊？", {"A": "8", "B": "9", "C": "10", "D": "12"}, "C", "每個外角=180°-144°=36°；正多邊形邊數 n=360°÷36°=10，選 C。", "先用內外角互補找外角，再用 360° 除以單一外角。", ["求單一外角 180°-144°=36°。", "正多邊形外角總和為 360°。", "邊數 n=360÷36。", "計算得 n=10。", "所以選 C。"], "medium"),
    make(10, "某多邊形的內角和為 1440°，它是幾邊形？", {"A": "8", "B": "9", "C": "10", "D": "12"}, "C", "套用 (n-2)×180°=1440°，得 n-2=8，n=10，選 C。", "把內角和公式看成未知邊數的一次方程，再解 n。", ["設多邊形有 n 邊。", "列式 (n-2)×180=1440。", "兩邊除以 180 得 n-2=8。", "加 2 得 n=10。", "所以選 C。"], "medium"),
]

